function openVisualSelect(){
  _visualReturnFocus=document.activeElement;
  const pop=$('charVisualPop');pop.style.display='flex';
  _spawnEmbers();
  const grid=$('visualGrid');grid.replaceChildren();
  CHAR_VISUALS.forEach((ch,ci)=>{
    const ico=document.createElement('button');ico.type='button';ico.className='cs-ico';ico.setAttribute('data-vi',ci);
    ico.title=_TL(ch.name);
    const ring=document.createElement('div');ring.className='cs-ico-ring';
    if(ch.emblemImg){const img=document.createElement('img');img.src=ch.emblemImg;img.alt='';ring.appendChild(img)}
    const label=document.createElement('div');label.className='lbl';label.textContent=_TL(ch.tab||ch.name);
    ico.replaceChildren(ring,label);
    if(ch.comingSoon){ico.classList.add('locked');const badge=document.createElement('span');badge.className='cs-soon';badge.textContent=_TL('출시 준비 중');ico.appendChild(badge);ico.title+=' — '+_TL('출시 준비 중')}
    ico.onclick=()=>selectVisual(ci);
    grid.appendChild(ico);
  });
  selectVisual(_pendingVisualIdx||0);
  _resetVisualInfoScroll();
  const target=grid.querySelector('.cs-ico.sel')||$('visualCancelBtn');if(target)target.focus({preventScroll:true});
}

selectVisual.text:
function selectVisual(ci){
  const ch=CHAR_VISUALS[ci],pop=$('charVisualPop');if(!ch||!pop||pop.style.display!=='flex')return;
  const changed=_pendingVisualIdx!==ci;
  const request=++_visualPreviewSeq,isCurrent=()=>request===_visualPreviewSeq&&pop.style.display==='flex';
  _pendingVisualIdx=ci;
  $('csPortrait').parentElement.classList.toggle('silvertail-keyart',!!ch.keyart);
  const locked=!!ch.comingSoon;
  $('charVisualPop').classList.toggle('release-locked',locked);
  $('visualCreateBtn').disabled=locked;
  $('visualCreateBtn').textContent=_TL(locked?'출시 준비 중':'생성');
  $('csReleaseLabel').textContent=locked?_TL('출시 준비 중'):'';
  // 중앙: 아이들 영상 있으면 우선 재생(실패·지연 시 정적 누끼로 폴백), 없으면 정적 누끼
  const idle=$('csIdleVid'), port=$('csPortrait');
  const _showStatic=()=>{
    if(!isCurrent())return;
    if(idle){idle.classList.remove('on');idle.pause&&idle.pause();}
    if(port){port.style.display='';port.classList.add('swap');
      setTimeout(()=>{if(!isCurrent())return;port.src=ch.portrait||'';port.classList.remove('swap');},180);}
    const _sc=$('csScene');if(_sc){if(ch.scene)_sc.style.backgroundImage="url('"+ch.scene+"')";_sc.style.opacity=ch.scene?'1':'0';}
  };
  if(ch.idleVid&&idle){
    if(ch.poster)idle.poster=ch.poster;             // 로딩 중 즉시 첫 프레임 표시
    if(idle.getAttribute('src')!==ch.idleVid||idle.error){idle.classList.remove('on');idle.src=ch.idleVid;idle.load&&idle.load();}
    idle.defaultPlaybackRate=ch.idleRate||1;idle.playbackRate=idle.defaultPlaybackRate;
    clearTimeout(idle._csT);
    idle.onerror=_showStatic;                         // 로드/디코드 실패 → 정적 폴백
    idle.oncanplay=()=>{if(isCurrent())clearTimeout(idle._csT);};
    idle._csT=setTimeout(()=>{if(isCurrent()&&idle.readyState<2)_showStatic();},5000); // 5초 스톨 → 폴백
    idle.classList.add('on');if(port)port.style.display='none';
    const _pr=idle.play&&idle.play();if(_pr&&_pr.catch)_pr.catch(()=>{}); // autoplay 막혀도 poster 프레임 유지
  }else{
    _showStatic();
  }
  // 좌측 정보
  $('csClsName').textContent=_TL(ch.job||ch.cls||'');
  $('csCharName').textContent=_TL(ch.name);
  $('csCharDesc').textContent=_TL(ch.desc);
  const th=$('csThumb');if(th){const _tp=ch.bust||ch.portrait;th.style.backgroundImage=_tp?"url('"+_tp+"')":'';th.classList.toggle('silvertail-keyart',!!ch.keyart);}
  const aura=$('csAura');if(aura&&ch.aura)aura.style.setProperty('--aura',ch.aura);
  // 배경 씬 — 아이들 영상 있으면 그게 전체를 덮으므로 배경 레이어는 끔
  const sc=$('csScene'), vid=$('csSceneVid');
  if(ch.idleVid){
    if(sc)sc.style.opacity='0';
    if(vid){vid.classList.remove('on');vid.pause&&vid.pause();}
  }else{
    if(sc){sc.style.opacity='0';if(ch.scene)setTimeout(()=>{if(!isCurrent())return;sc.style.backgroundImage="url('"+ch.scene+"')";sc.style.opacity='1';},180);}
    if(vid){
      if(ch.sceneVid){if(vid.getAttribute('src')!==ch.sceneVid||vid.error){vid.src=ch.sceneVid;}vid.classList.add('on');vid.play&&vid.play().catch(()=>{});}
      else{vid.classList.remove('on');vid.pause&&vid.pause();}
    }
  }
  // 우측 플레이 방식
  const tr=$('csTraits');
  if(tr){tr.innerHTML=(ch.traits||[]).map(t=>
    '<div class="cs-trait"><div class="ti"><span class="ti-g">'+t[0]+'</span></div><div><div class="tt">'+escHtml(_TL(t[1]))
    +'</div><div class="td">'+escHtml(_TL(t[2]))+'</div></div></div>').join('');}
  // 아이콘 레일 선택 표시
  const grid=$('visualGrid');if(grid)grid.querySelectorAll('.cs-ico').forEach((c,i)=>{c.classList.toggle('sel',i===ci);c.setAttribute('aria-pressed',String(i===ci));});
  if(changed)_resetVisualInfoScroll();
  // 좌우 패널 등장 애니메이션 (재트리거)
  ['csLeft','csRight'].forEach(id=>{const el=$(id);if(el){el.classList.remove('in');void el.offsetWidth;el.classList.add('in');}});
}

_visualSelectKeydown.text:
function _visualSelectKeydown(e){
  const pop=$('charVisualPop');if(!pop||pop.style.display!=='flex'||e.isComposing||e.keyCode===229)return;
  if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(!e.repeat)$('visualCancelBtn').click();return;}
  const icons=[...$('visualGrid').querySelectorAll('.cs-ico')];
  if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)&&icons.includes(document.activeElement)){
    e.preventDefault();e.stopPropagation();
    const index=icons.indexOf(document.activeElement),last=icons.length-1;
    const step=(e.key==='ArrowRight'?1:-1)*(document.documentElement.dir==='rtl'?-1:1);
    const next=e.key==='Home'?0:e.key==='End'?last:Math.max(0,Math.min(last,index+step));
    icons[next].click();icons[next].focus({preventScroll:true});return;
  }
  if(e.key!=='Tab')return;
  const details=[$('csLeft'),$('csRight')].filter(Boolean);
  const controls=[...details,...icons,$('visualCancelBtn'),$('visualCreateBtn')].filter(el=>el&&!el.disabled);
  if(!controls.length)return;
  e.preventDefault();e.stopPropagation();
  const index=controls.indexOf(document.activeElement);
  const next=index<0?(e.shiftKey?controls.length-1:0):(index+(e.shiftKey?-1:1)+controls.length)%controls.length;
  const target=controls[next];target.focus({preventScroll:true});
  if(details.includes(target))target.scrollIntoView({block:'start'});
}

doCreateChar.text:
async function doCreateChar(name,visualIdx){
  if($('createBtn').disabled)return;
  if(CHAR_VISUALS[visualIdx]?.comingSoon){setStatus(_TL('출시 준비 중'),true);return}
  const request=_characterLoadSeq;
  $('createBtn').disabled=true;setStatus(_TL('생성 중...'));
  if(_testMode){
    try{
    try{
      if(_LOBBY_BUILD==='demo')throw new Error('demo local');
      const res=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slot:name,data:{ts:Date.now(),charIdx:visualIdx}})});
      if(request!==_characterLoadSeq)return;
      if(!res.ok)throw new Error('no server');
      const j=await res.json();
      if(request!==_characterLoadSeq)return;
      $('createBtn').disabled=false;
      if(!j.ok){_showCreateFailure(name,_TL('생성 실패: ')+(j.error||_TL('알 수 없는 오류')));return}
      $('charName').value='';setStatus('');await _afterCharacterCreated(name,visualIdx);
    }catch(e){
      if(request!==_characterLoadSeq)return;
      const _LS_PREFIX='hellsave_demo_';const MAX_LS=5;
      for(let i=0;i<MAX_LS;i++){const raw=localStorage.getItem(_LS_PREFIX+i);if(raw){try{const d=JSON.parse(raw);if(d.name===name){_showCreateFailure(name,_TL('이미 같은 이름의 캐릭터가 있습니다.'));return}}catch(pe){}}}
      let _slot=-1;for(let i=0;i<MAX_LS;i++){if(!localStorage.getItem(_LS_PREFIX+i)){_slot=i;break}}
      if(_slot<0){_showCreateFailure(name,_TL('슬롯이 가득 찼습니다.'));return}
      localStorage.setItem(_LS_PREFIX+_slot,JSON.stringify({name:name,ts:Date.now(),charIdx:visualIdx}));
      $('createBtn').disabled=false;$('charName').value='';setStatus('');await _afterCharacterCreated(name,visualIdx);
    }
    return;
    }catch(error){if(request===_characterLoadSeq)_showCreateFailure(name,_TL('생성 실패: ')+(error.message||_TL('알 수 없는 오류')))}
    finally{$('createBtn').disabled=false;}
    return;
  }
  let error=null;
  try{
    if(!currentUser||!currentUser.id)throw new Error(_TL('로그인 필요'));
    ({error}=await sb.from('characters').insert({user_id:currentUser.id,name:name,data:{charIdx:visualIdx}}));
  }catch(cause){error=cause||new Error(_TL('알 수 없는 오류'));}
  finally{$('createBtn').disabled=false;}
  if(request!==_characterLoadSeq)return;
  if(error){
    _showCreateFailure(name,error.code==='23505'?_TL('이미 같은 이름의 캐릭터가 있습니다.'):_TL('생성 실패: ')+(error.message||_TL('알 수 없는 오류')));return;
  }
  $('charName').value='';setStatus('');await _afterCharacterCreated(name,visualIdx);
}
